public class PooledConnectionManagerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static int idOf(FakeDbConnection c) {
        return c == null ? -1 : c.id();
    }

    public static void main(String[] args) {
        try {
            PooledConnectionManager pool = new PooledConnectionManager(2);
            check("a fresh pool of 2 has 2 idle connections", 2, pool.idleCount());
            check("a fresh pool has nothing in use", 0, pool.busyCount());

            FakeDbConnection first = pool.checkout();
            FakeDbConnection second = pool.checkout();
            check("the first checkout gives connection 1", 1, idOf(first));
            check("the second checkout gives connection 2", 2, idOf(second));
            check("an exhausted pool hands out null", -1, idOf(pool.checkout()));
            check("both connections are in use", 2, pool.busyCount());
            check("nothing is idle", 0, pool.idleCount());

            pool.release(first);
            check("releasing puts one back", 1, pool.idleCount());
            check("releasing the same connection twice changes nothing",
                    1, idleAfterDoubleRelease(pool, first));
            check("the released connection is handed out again", 1, idOf(pool.checkout()));

            pool.release(null);
            check("releasing null is ignored", 0, pool.idleCount());

            pool.closeAll();
            check("closeAll closes the connections", true,
                    first != null && first.isClosed() && second != null && second.isClosed());
            check("closeAll empties the pool", 0, pool.idleCount() + pool.busyCount());
            check("a closed pool hands out nothing", -1, idOf(pool.checkout()));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static int idleAfterDoubleRelease(PooledConnectionManager pool, FakeDbConnection c) {
        pool.release(c);
        return pool.idleCount();
    }
