import java.util.ArrayList;
import java.util.List;

/**
 * Provided -- do not edit. A stand-in for a real database connection: it only
 * knows its number and whether somebody has closed it.
 */
class FakeDbConnection {
    private final int id;
    private boolean closed;

    FakeDbConnection(int id) {
        this.id = id;
    }

    int id() {
        return id;
    }

    boolean isClosed() {
        return closed;
    }

    void close() {
        closed = true;
    }
}

/**
 * TASK: Model a fixed-size connection pool.
 *
 * The constructor creates "size" connections numbered 1, 2, ... size and puts
 * them all in the idle list. Nothing is ever created after that -- a pool
 * exists so that expensive connections are REUSED.
 *
 *   checkout()  removes and returns the LOWEST-NUMBERED idle connection,
 *               or null when every connection is already in use.
 *   release(c)  puts a checked-out connection back. Releasing null, or a
 *               connection that is not currently checked out, is IGNORED --
 *               it must never appear in the idle list twice.
 *   idleCount() / busyCount()  how many are free / in use.
 *   closeAll()  closes every connection (idle or busy) and empties the pool,
 *               so idleCount, busyCount and checkout all report "nothing left".
 *
 * Example: pool of 2 -> checkout() gives #1, then #2, then null.
 *          release(#1) -> idleCount 1, and the next checkout gives #1 again.
 */
public class PooledConnectionManager {

    private final List<FakeDbConnection> idle = new ArrayList<>();
    private final List<FakeDbConnection> busy = new ArrayList<>();

    public PooledConnectionManager(int size) {
        for (int i = 1; i <= size; i++) {
            idle.add(new FakeDbConnection(i));
        }
    }

    public FakeDbConnection checkout() {
        if (idle.isEmpty()) {
            return null;
        }
        int best = 0;
        for (int i = 1; i < idle.size(); i++) {
            if (idle.get(i).id() < idle.get(best).id()) {
                best = i;
            }
        }
        FakeDbConnection chosen = idle.remove(best);
        busy.add(chosen);
        return chosen;
    }

    public void release(FakeDbConnection connection) {
        if (connection == null) {
            return;
        }
        if (busy.remove(connection)) {
            idle.add(connection);
        }
    }

    public int idleCount() {
        return idle.size();
    }

    public int busyCount() {
        return busy.size();
    }

    public void closeAll() {
        for (FakeDbConnection c : idle) {
            c.close();
        }
        for (FakeDbConnection c : busy) {
            c.close();
        }
        idle.clear();
        busy.clear();
    }
}
